import sys

def add(a, b):
    return a + b

class Calculator:
    def __init__(self, a, b):
        self.a = a
        self.b = b

    def multiply(self):
        return self.a * self.b

    def subtract(self):
        return self.a - self.b

def main():
    line = sys.stdin.readline().strip()
    if not line:
        return
    parts = line.split()
    if len(parts) < 3:
        return

    data_type = parts[0].lower()
    val1_str = parts[1]
    val2_str = parts[2]

    if data_type == 'int':
        a = int(val1_str)
        b = int(val2_str)
    elif data_type == 'double':
        a = float(val1_str)
        b = float(val2_str)
    elif data_type == 'string':
        a = val1_str
        b = val2_str
    else:
        return

    calc = Calculator(a, b)

    if data_type in ('int', 'double'):
        print(f"Addition: {add(a, b)}")
        print(f"Subtraction: {calc.subtract()}")
        print(f"Multiplication: {calc.multiply()}")
    else:
        print(f"Addition: {add(a, b)}")
        print(f"Subtraction: Not Supported")
        print(f"Multiplication: Not Supported")

if __name__ == "__main__":
    main()
